def resolve_expression(self, query=None, allow_joins=True, reuse=None, summarize=False, for_save=False):
    if hasattr(self, 'source_expressions'):
        # Propagate for_save down to all children
        self.source_expressions = [
            expression.resolve_expression(query, allow_joins, reuse, summarize, for_save)
            for expression in self.source_expressions
        ]
    return self

def resolve_expression(self, *args, for_save=False, **kwargs):
    # Resolve the expression to its final form. Propagate the for_save flag correctly.
    res = self
    for node in self.get_source_expressions():
        node_resolved = node.resolve_expression(*args, for_save=for_save, **kwargs)
        res = res.replace_expression(node, node_resolved)
    # If for_save is True, ensure that get_db_prep_save is called appropriately.
    if for_save and hasattr(res, 'get_db_prep_save'):
        res = res.get_db_prep_save(self._output_field)
    return res
